                                                        ? "bg-orange-500"
                                                        : "bg-purple-500"
                                                } ${expandedIndex === index ? "ring-2 ring-blue-500" : ""}`}
                                                onClick={() => toggleExpand(index)}
                                            >
                                                <CardHeader className="pb-2">
